import{_ as e,o,c as d,a2 as a}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"MCP Tools","description":"","frontmatter":{},"headers":[],"relativePath":"mcp-tools/overview.md","filePath":"mcp-tools/overview.md","lastUpdated":1784744785000}'),n={name:"mcp-tools/overview.md"};function s(r,t,i,c,l,p){return o(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="mcp-tools" tabindex="-1">MCP Tools <a class="header-anchor" href="#mcp-tools" aria-label="Permalink to &quot;MCP Tools&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>swag2mcp provides <strong>19 MCP tools</strong> that give an LLM agent full access to your APIs through the Model Context Protocol. These tools cover the complete workflow: discovering what APIs are available, navigating the spec hierarchy, searching and inspecting endpoints, executing API calls, and working with large responses.</p><h3 id="what-the-tools-solve" tabindex="-1">What the tools solve <a class="header-anchor" href="#what-the-tools-solve" aria-label="Permalink to &quot;What the tools solve&quot;">​</a></h3><ul><li><strong>Discovery</strong> — the LLM can find specs, collections, and tags without knowing IDs in advance</li><li><strong>Navigation</strong> — drill down from spec → collection → tag → endpoint in a structured hierarchy</li><li><strong>Search</strong> — full-text search across all endpoints when you don&#39;t have an ID</li><li><strong>Inspection</strong> — get the full OpenAPI operation object before making a call</li><li><strong>Execution</strong> — invoke real API calls with automatic authentication</li><li><strong>Large response handling</strong> — outline, compress, and slice oversized responses that don&#39;t fit inline</li></ul><h3 id="read-only-vs-mutable" tabindex="-1">Read-only vs Mutable <a class="header-anchor" href="#read-only-vs-mutable" aria-label="Permalink to &quot;Read-only vs Mutable&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Count</th><th>Tools</th></tr></thead><tbody><tr><td><strong>Read-only</strong></td><td>17</td><td>All discovery, endpoint, search, inspect, info, and response tools</td></tr><tr><td><strong>Mutable</strong></td><td>2</td><td><code>invoke</code> (makes real HTTP calls), <code>auth</code> (retrieves tokens)</td></tr></tbody></table><p>Read-only tools are marked with <code>ReadOnlyHint=true</code> and <code>IdempotentHint=true</code> in the MCP protocol, signaling to the LLM that they are safe to call without side effects.</p><h3 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h3><p>All tools return errors as structured <code>LLMError</code> objects with a machine-readable code and a human-readable message that explains what went wrong and what to do next:</p><table tabindex="0"><thead><tr><th>Error code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>Invalid input (bad ID format, missing required fields)</td></tr><tr><td><code>not_found</code></td><td>Entity not found in the index or workspace</td></tr><tr><td><code>rate_limit</code></td><td>Second <code>invoke</code> call within 10 seconds on the same endpoint</td></tr><tr><td><code>invoke_error</code></td><td>HTTP call failure, download failure</td></tr><tr><td><code>auth_error</code></td><td>Auth token retrieval failure</td></tr><tr><td><code>config_error</code></td><td>Config file load or save failure</td></tr><tr><td><code>parse_error</code></td><td>Spec file parse failure</td></tr></tbody></table><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Tools</th><th>Description</th></tr></thead><tbody><tr><td><strong>Discovery</strong></td><td><code>spec_list</code>, <code>spec_by_id</code>, <code>collection_by_spec</code>, <code>collection_by_id</code>, <code>tag_by_spec</code>, <code>tag_by_collection</code>, <code>tag_by_id</code></td><td>Navigate the spec hierarchy: find specs, collections, and tags</td></tr><tr><td><strong>Endpoints</strong></td><td><code>endpoint_by_spec</code>, <code>endpoint_by_collection</code>, <code>endpoint_by_tag</code>, <code>endpoint_by_id</code></td><td>View endpoints at different levels of the hierarchy</td></tr><tr><td><strong>Execution</strong></td><td><code>search</code>, <code>inspect</code>, <code>invoke</code></td><td>Search, inspect the full contract, and call APIs</td></tr><tr><td><strong>Utilities</strong></td><td><code>auth</code>, <code>info</code>, <code>response_outline</code>, <code>response_compress</code>, <code>response_slice</code></td><td>Auth tokens, runtime info, and large response handling</td></tr><tr><td><strong>Skills</strong></td><td><a href="/mcp-tools/skills">Formatting guide</a></td><td>Customize how tool responses are displayed</td></tr></tbody></table><h2 id="full-list" tabindex="-1">Full List <a class="header-anchor" href="#full-list" aria-label="Permalink to &quot;Full List&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>List all API specifications in the workspace</td></tr><tr><td><code>spec_by_id</code></td><td>Get detailed spec information with collections</td></tr><tr><td><code>collection_by_spec</code></td><td>List collections within a spec</td></tr><tr><td><code>collection_by_id</code></td><td>Get collection details with tags</td></tr><tr><td><code>tag_by_spec</code></td><td>List all tags across a spec</td></tr><tr><td><code>tag_by_collection</code></td><td>List tags within a collection</td></tr><tr><td><code>tag_by_id</code></td><td>Get tag details (ID, title, method count)</td></tr><tr><td><code>endpoint_by_spec</code></td><td>List all endpoints in a spec</td></tr><tr><td><code>endpoint_by_collection</code></td><td>List endpoints in a collection</td></tr><tr><td><code>endpoint_by_tag</code></td><td>List endpoints in a tag</td></tr><tr><td><code>endpoint_by_id</code></td><td>Quick endpoint summary (method, path, summary)</td></tr><tr><td><code>search</code></td><td>Full-text search across all endpoints</td></tr><tr><td><code>inspect</code></td><td>Full OpenAPI operation details (parameters, schemas)</td></tr><tr><td><code>invoke</code></td><td>Execute a real API call</td></tr><tr><td><code>auth</code></td><td>Get auth token or headers for a spec</td></tr><tr><td><code>info</code></td><td>Runtime information (version, specs, config)</td></tr><tr><td><code>response_outline</code></td><td>Structural summary of a large response file</td></tr><tr><td><code>response_compress</code></td><td>Compress a large response to fit inline</td></tr><tr><td><code>response_slice</code></td><td>Extract a fragment of a large response</td></tr></tbody></table><h2 id="navigation-hierarchy" tabindex="-1">Navigation Hierarchy <a class="header-anchor" href="#navigation-hierarchy" aria-label="Permalink to &quot;Navigation Hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>When you don&#39;t have an ID, use <code>search</code> to find endpoints by query. When <code>invoke</code> returns a <code>fileRef</code> (response too large), use <code>response_outline</code> → <code>response_compress</code> or <code>response_slice</code> to explore the data.</p>`,18)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
